effect.shader:
const float PI = 3.14159265;

// A gaussiana de meio-lado `lado` (em pixels de `img`) no eixo `passo`, na mesma ordem de contas do AM: os pesos
// tirados um do outro por multiplicação e duas amostras juntas numa leitura (a posição entre elas pelo peso).
vec4 desfocar(sampler2D img, vec2 passo, vec2 st, float lado) {
    if (strength <= 0.0) return vec4(0.0);
    float sigma = lado / 2.14596602;
    highp vec3 g;
    g.x = 1.0 / (sqrt(2.0 * PI) * sigma);
    g.y = exp(-0.5 / (sigma * sigma));
    g.z = g.y * g.y;
    vec4 soma = vec4(0.0);
    highp float total = 0.0;
    soma += texture(img, st) * g.x;
    total += g.x;
    for (float i = 1.0; i <= lado; i += 2.0) {
        float d0 = i;
        float d1 = i + 1.0;
        g.xy *= g.yz;
        total += 2.0 * g.x;
        float p0 = g.x;
        g.xy *= g.yz;
        total += 2.0 * g.x;
        float p1 = g.x;
        float par = p0 + p1;
        float d = (d0 * p0 + d1 * p1) / par;
        vec2 stL = st - d * passo;
        vec2 stR = st + d * passo;
        soma += texture(img, stL) * par;
        soma += texture(img, stR) * par;
    }
    return soma / total;
}

// O meio-lado: Intensidade ÷ 2 × 1,14 ÷ 4 ÷ 3 da diagonal da imagem CHEIA (o `acPreviewSize` do AM).
float ladoDoDesfoque() {
    return strength / 2.0 * 1.14 / 4.0 / 3.0 * length(vec2(textureSize(pre, 0)));
}

void main() {
    if (acPass == 0) {
        vec4 c = texture(inputImg, acScreenNorm);
        fragColor = vec4(c.rgb * c.a, c.a);
        return;
    }
    if (acPass == 1) {
        fragColor = texture(pre, acScreenNorm);
        return;
    }
    if (acPass == 2) {
        vec2 passo = vec2(1.0 / vec2(textureSize(downImg, 0)).x, 0.0);
        fragColor = desfocar(downImg, passo, acScreenNorm, ladoDoDesfoque());
        return;
    }
    if (acPass == 3) {
        // Na tela a entrada chega de pé (t = 0 embaixo, como no AM): o passo aponta para CIMA e a soma do par fica na
        // mesma ordem da dele (o de baixo primeiro). Invertida, a soma em float mudaria o último bit.
        float cima = acEntradaDePe == 1 ? 1.0 : -1.0;
        vec2 passo = vec2(0.0, cima / vec2(textureSize(hblur, 0)).y);
        vec4 r = desfocar(hblur, passo, acScreenNorm, ladoDoDesfoque());
        fragColor = strength <= 0.0 ? texture(pre, acScreenNorm) : r;
        return;
    }

    // Até 0,0001 o AM tira o efeito da lista (o script dele não liga o grupo de shader): a camada como está.
    if (!(strength > 0.0001)) {
        fragColor = texture(inputImg, acScreenNorm);
        return;
    }
    vec4 c = texture(vblur, acScreenNorm);
    fragColor = c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}
